def edu(level, th, en, field, inst, country, year=None, start=None, thesis=None, honors=None):
    return {k: v for k, v in dict(level=level, degreeTh=th, degreeEn=en, field=field, institution=inst, country=country, year=year, startYear=start, thesis=thesis, honors=honors).items() if v is not None}

def job(pos, org=None, frm=None, to=None, text=None):
    return {k: v for k, v in dict(position=pos, org=org, orgText=text, **{"from": frm, "to": to}).items() if v is not None}

def ev(kind, date, th, en, end=None, approx=False, org=None, country=None, url=None, source=None, desc_th=None, desc_en=None, org_text=None):
    return {k: v for k, v in dict(kind=kind, date=date, end=end, approx=approx or None, titleTh=th, titleEn=en, org=org, orgText=org_text, country=country,
                                  url=url, source=source, descTh=desc_th, descEn=desc_en).items() if v is not None}

